 private static BufferedImage raster(String content,int[] style){Font font=new Font(new String[]{Font.SANS_SERIF,Font.SERIF,Font.MONOSPACED}[style[2]],style[3],style[0]);BufferedImage metrics=new BufferedImage(1,1,2);Graphics2D g=metrics.createGraphics();g.setFont(font);FontMetrics fm=g.getFontMetrics();java.util.List<String> lines=new java.util.ArrayList<>();for(String paragraph:content.split("\n",-1)){String line="";for(String word:paragraph.split(" ")){if(!line.isEmpty()&&fm.stringWidth(line+" "+word)>style[4]){lines.add(line);line=word;}else line+=line.isEmpty()?word:" "+word;}lines.add(line);}int width=Math.max(8,Math.min(6000,style[4])),height=Math.min(6000,Math.max(8,fm.getHeight()*lines.size()+8));BufferedImage out=new BufferedImage(width,height,2);Graphics2D draw=out.createGraphics();draw.setFont(font);draw.setColor(new Color(style[1],true));draw.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);int y=fm.getAscent()+4;for(String line:lines){draw.drawString(line,4,y);y+=fm.getHeight();}draw.dispose();g.dispose();return out;}
 public static void text(JFrame owner,int color,int size,int x,int y,Runnable changed){edit(owner,null,-1,"Texto",new int[]{Math.max(12,size*3),color,0,0,400},x,y,changed);}
